    for dec in decs:
        for jump in [11,15,20,30]:
            build(dec,jump,nmov,"/app/dev/tmpD.red")
            r=test("/app/dev/tmpD.red",100)
            w={k:v[0] for k,v in r.items()}
            ok=all([w['stone']>=75,w['paper']>=75,w['vampire']>=75,w['snake']>=33,w['g2-clear']>=33])
            print(f"movs={nmov+1} dec={dec} jump={jump}", w, "PASS" if ok else "", flush=True)
PY

