import subprocess
OPP = ["stone","paper","vampire","snake","g2-clear"]
def build(path, dec=4000, jump=11, gstep=25, nspl=1, pad=0, gphase=12):
    L=[";redcode-94",";name Hybrid",";assert CORESIZE == 8000 && MAXCYCLES == 80000",
       f"dec     equ {dec}",f"jump    equ {jump}",f"gstep   equ {gstep}","gate    equ sptr-3",
       "        org boom","sptr    dat    1, 0","boom    spl    #dec, jump"]
    body=["clear   mov.i  *sptr, >gate"]
    for _ in range(nspl-1): body.append("        mov.i  *sptr, >gate")
    body += ["        mov.i  dbomb, @gptr","        add.ab #gstep, gptr","        djn.f  clear, }boom"]
    ncode=2+len(body)   # sptr,boom + body
    gp = gphase-(ncode+1)   # gptr index = ncode+1 (dbomb at ncode)
    L += body + ["dbomb   dat    0, jump", f"gptr    dat    0, {gp}"]
    for i in range(pad): L.append(f"        dat    {i+1}, {i+2}")
    L.append("        end")
    open(path,"w").write("\n".join(L)+"\n")
def test(path, r=100, opps=OPP):
    out={}
    for o in opps:
        res = subprocess.run(["pmars","-b","-r",str(r),"-f",path,f"warriors/{o}.red"],capture_output=True,text=True,cwd="/app")
        line=[l for l in res.stdout.splitlines() if l.startswith("Results:")]
        if not line: return None
        w,l,t = map(int,line[0].split()[1:4]); out[o]=w
    return out
def margin(w):
    return min(w['stone']-75,w['paper']-75,w['vampire']-75,w['snake']-33,w['g2-clear']-33)
