import subprocess, itertools, json, os, sys
OPP = ["stone","paper","vampire","snake","g2-clear"]
THR = {"stone":75,"paper":75,"vampire":75,"snake":33,"g2-clear":33}
def build(path, dec, jump, nmov=2, stream="}", pad=0, sa=1, name="Stunner"):
    L=[";redcode-94",f";name {name}",";assert CORESIZE == 8000 && MAXCYCLES == 80000",
       f"dec     equ {dec}",f"jump    equ {jump}","gate    equ sptr-3",
       "        org boom",f"sptr    dat    {sa}, 0","boom    spl    #dec, jump",
       "clear   mov.i  *sptr, >gate"]
    for _ in range(nmov-1): L.append("        mov.i  *sptr, >gate")
    L.append(f"        djn.f  clear, {stream}boom")
    for i in range(pad): L.append(f"        dat    {i+1}, {i+2}")
    L.append("        end")
    open(path,"w").write("\n".join(L)+"\n")
def run(path,o,r=100):
    res = subprocess.run(["pmars","-b","-r",str(r),"-f",path,f"warriors/{o}.red"],capture_output=True,text=True,cwd="/app")
    line=[l for l in res.stdout.splitlines() if l.startswith("Results:")]
    if not line: return None
    return tuple(map(int,line[0].split()[1:4]))
def evaluate(path, order=("stone","snake","g2-clear","paper","vampire"), early=True):
    w={}
    for o in order:
        r=run(path,o)
        if r is None: return None,None
        w[o]=r[0]
        if early and r[0] < THR[o]-6: break
    m=min((w.get(o,-99)-THR[o]) for o in OPP)
    return w,m
PY
